import{_ as o,o as t,c as a,a3 as r}from"./chunks/framework.cNy3aYYk.js";const h=JSON.parse('{"title":"Customer Portal — Developer Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Customer Portal — Developer Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/customer-portal"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Customer Portal — Developer Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/customer-portal"}]]},"headers":[],"relativePath":"developer-guide/customer-portal.md","filePath":"developer-guide/customer-portal.md","lastUpdated":1791474066000}'),c={name:"developer-guide/customer-portal.md"};function d(l,e,s,i,n,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="customer-portal-—-developer-guide" tabindex="-1">Customer Portal — Developer Guide <a class="header-anchor" href="#customer-portal-—-developer-guide" aria-label="Permalink to &quot;Customer Portal — Developer Guide&quot;">​</a></h1><p>Marketplace Operations module (<code>customer-portal</code> <strong>1.3.0</strong>). Flat namespaces (no <code>Modules/</code> package). Invite-only Contact accounts with a dedicated Sanctum guard.</p><h2 id="identity" tabindex="-1">Identity <a class="header-anchor" href="#identity" aria-label="Permalink to &quot;Identity&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>Staff</th><th>Portal</th></tr></thead><tbody><tr><td>Model</td><td><code>User</code></td><td><code>PortalUser</code></td></tr><tr><td>Guard</td><td><code>tenant-api</code></td><td><code>portal-api</code></td></tr><tr><td>Provider</td><td><code>users</code></td><td><code>portal_users</code></td></tr><tr><td>Permissions</td><td>Spatie <code>tenant-api</code></td><td>None — <code>PortalRecordScope</code> only</td></tr><tr><td>Token name</td><td><code>tenant-token</code></td><td><code>portal-token</code></td></tr></tbody></table><p><code>PortalUser</code>: <code>contact_id</code> (unique per tenant), <code>email</code>, <code>password</code>, <code>status</code> (<code>invited</code> | <code>active</code> | <code>disabled</code>), invite token hash/expiry. Soft deletes. Email must match Contact email at invite.</p><h2 id="services" tabindex="-1">Services <a class="header-anchor" href="#services" aria-label="Permalink to &quot;Services&quot;">​</a></h2><ul><li><code>App\\Services\\Central\\PortalWorkspaceLookupService</code> — email → workspaces that already have that portal account (<code>POST /api/central/v1/public/portal-workspaces</code>)</li><li><code>App\\Services\\Tenant\\CustomerPortal\\PortalUserService</code> — invite / resend / disable / enable / accept invite</li><li><code>App\\Services\\Tenant\\CustomerPortal\\PortalAuthService</code> — credentials / magic-link / logout / token / password reset</li><li><code>App\\Services\\Tenant\\CustomerPortal\\PortalRecordScope</code> — contact + optional company scope</li><li>Document services: <code>PortalInvoiceService</code>, <code>PortalPaymentService</code>, <code>PortalQuotationService</code>, <code>PortalContractService</code></li><li><code>PortalProjectService</code> — shared projects (<code>portal_visible</code> + <code>PortalRecordScope</code>); customer-visible tasks (<code>visible_to_portal</code>); filtered timeline</li><li><code>PortalHelpDeskService</code> — create stamps <code>contact_id</code> / <code>company_id</code>; notes set <code>portal_user_id</code> and <code>is_internal = false</code>; customer reply reopens closed/resolved via <code>HelpDeskTicketService::reopenFromCustomerReply</code></li><li><code>PortalKnowledgeBaseService</code> — published articles only (soft <code>knowledge-base</code>)</li></ul><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><ul><li>Staff: <code>src/pages/customer-portal/</code>, Contact invite actions, nav under Operations</li><li>Portal SPA: <code>src/pages/portal/*</code>, <code>PortalLayout</code> / <code>PortalAuthLayout</code>, <code>usePortalAuthStore</code> (isolated token storage). Shared-host login/forgot/magic-link: email first, then searchable company picker from the central lookup (invite/reset/magic links still carry <code>?workspace=</code>).</li><li>Routes: <code>/#/portal/login</code>, magic-link request + <code>/#/portal/magic-login/:token</code>, invite/reset, Security (2FA), Knowledge Base, authenticated <code>/#/portal/...</code></li><li><code>FrontendUrl::portalInvite()</code> / <code>portalResetPassword()</code> / <code>portalMagicLogin()</code></li></ul><h2 id="auth-depth-1-3-0" tabindex="-1">Auth depth (1.3.0) <a class="header-anchor" href="#auth-depth-1-3-0" aria-label="Permalink to &quot;Auth depth (1.3.0)&quot;">​</a></h2><ul><li><strong>Magic link:</strong> <code>POST /portal/auth/magic-link</code> (generic success; Active accounts only; Central mail) + <code>POST /portal/auth/magic-link/consume</code>. Single-use hashed token on <code>portal_users</code> (15 min TTL).</li><li><strong>2FA:</strong> Fortify TOTP on <code>PortalUser</code> (<code>two_factor_*</code> columns). Login and magic-link consume return <code>two_factor_required</code> + <code>challenge_token</code> when enabled; <code>POST /portal/auth/two-factor-challenge</code> issues the portal token. Manage under <code>auth:portal-api</code> → <code>/portal/auth/two-factor/*</code> (same shape as staff <code>/me/two-factor</code>).</li><li><strong>Public KB:</strong> <code>GET /portal/knowledge-base</code>, <code>/{id}</code> — published-only; soft entitlement.</li></ul><h2 id="help-desk-note-authorship" tabindex="-1">Help Desk note authorship <a class="header-anchor" href="#help-desk-note-authorship" aria-label="Permalink to &quot;Help Desk note authorship&quot;">​</a></h2><p><code>help_desk_notes.portal_user_id</code> (nullable) — catalog <strong>help-desk 1.12.0 → 1.13.0</strong>. Staff resources expose <code>portal_author</code> when present. <strong>1.14.0</strong> adds <code>is_internal</code>; portal never receives internal notes. Customer Portal <strong>1.2.0</strong> adds public reply attachments + TipTap UI. <strong>help-desk 1.15.0</strong> reopens closed/resolved on customer public reply (portal + email) and notifies assignee (<code>help_desk.customer_reply</code>; mail gated by <code>email_notifications.help_desk_customer_reply</code>, default off).</p><h2 id="portal-projects-tasks-1-1-0" tabindex="-1">Portal projects / tasks (1.1.0) <a class="header-anchor" href="#portal-projects-tasks-1-1-0" aria-label="Permalink to &quot;Portal projects / tasks (1.1.0)&quot;">​</a></h2><p>Two gates — both required for a task to appear in the portal:</p><ol><li>Project <code>portal_visible = true</code> and linked to the portal Contact or Company (<code>PortalRecordScope</code>)</li><li>Task <code>visible_to_portal = true</code> (default <code>false</code> — internal)</li></ol><p>Staff set both toggles on project/task forms when Customer Portal is installed. Unsharing a project clears all of that project&#39;s task portal flags. Soft modules: <code>projects</code> for list/show/timeline; <code>tasks</code> for nested tasks. Timeline exposes only customer-safe activity types (<code>created</code>, <code>status_changed</code>, <code>milestone_*</code> completed/updated/created) — no assignee/members/notes internals.</p><h2 id="hard-exclusions-still-deferred" tabindex="-1">Hard exclusions (still deferred) <a class="header-anchor" href="#hard-exclusions-still-deferred" aria-label="Permalink to &quot;Hard exclusions (still deferred)&quot;">​</a></h2><p>Online checkout, portal passkeys.</p>',19)])])}const m=o(c,[["render",d]]);export{h as __pageData,m as default};
